    const raw = prefix + '-' + String(position).padStart(3, '0');
    assert.deepEqual(readParcel(raw), { zone, position });
    assert.equal(forChute(raw), zone + ':' + position);
  }
}
const deferred = { deferred: true };
for (const raw of [deferred, null, 42, 'X-007', 'N-07', 'S-1000', ['N-007']]) {
  assert.equal(readParcel(raw), null);
  assert.equal(forChute(raw), '');
}
