  ['N-007', { zone: 'north', position: 7 }],
  ['S-999', { zone: 'south', position: 999 }],
  [deferred, null],
]) {
  const result = execFileSync('npm', ['run', '--silent', 'read', '--', JSON.stringify(raw)], { encoding: 'utf8' });
  assert.deepEqual(JSON.parse(result), expected);
}
console.log('OK: 2,000 labels through readParcel and forChute, 7 rejected values, and 3 CLI cases');
